import java.util.Objects;
import java.util.Optional;

/** Separates Agent Session, Host command, and HCP delivery facts. */
public final class CanonicalFacts {
    private CanonicalFacts() {}

    public record AgentSessionLog(List<LogItem> items, long nextSeq) {
        public AgentSessionLog {
            items = List.copyOf(items);
            if (nextSeq < 1) {
                throw new IllegalArgumentException("nextSeq must be positive");
            }
            long expected = 1;
            for (LogItem item : items) {
                if (item.seq() != expected++) {
                    throw new IllegalArgumentException("session log seq must be contiguous");
                }
            }
            if (expected != nextSeq) {
                throw new IllegalArgumentException("nextSeq must follow the final item");
            }
        }
    }

    public record LogItem(long seq, LogItemKind kind, String id, Optional<String> parentId, Map<String, Object> data) {
        public LogItem {
            if (seq < 1) {
                throw new IllegalArgumentException("seq must be positive");
            }
            Objects.requireNonNull(kind, "kind");
            requireText(id, "id");
            Objects.requireNonNull(parentId, "parentId");

